def cleanup(func):
    def wrapper(*args, **kwargs):
        print(f"Starting cleanup on {func.__name__}")
        try:
            result = func(*args, **kwargs)
        except Exception as e:
            print(f"Cleanup failed: {e}")
        finally:
            print(f"Cleanup complete on {func.__name__}")
        return result

# Usage
